module freq_divbyodd(
	input clk, rst_n,
	output clk_div
);
	//TODO: Your HW3b solution below
	reg [2:0] cnt1, cnt2;
	reg clk_div1, clk_div2;

	always@(posedge clk or negedge rst_n) begin
		if(!rst_n) 
			cnt1 <= 3'd0;
		else if(cnt1==4'd4) 
			cnt1 <= 3'd0;
		else
			cnt1 <= cnt1 + 1;
	end

	always@(~clk or negedge rst_n) begin
		if(!rst_n) 
			cnt2 <= 3'd0;
		else if(cnt2==4'd4) 
			cnt2 <= 3'd0;
		else
			cnt2 <= cnt2 + 1;
	end

	always@(posedge clk or negedge rst_n) begin
		if(!rst_n) 
			clk_div1 <= 1'b0;
		else if(cnt1<2) 
			clk_div1 <= 1'b1;
		else 
			clk_div1 <= 1'b0;
	end

	always@(negedge clk or negedge rst_n) begin
		if(!rst_n) 
			clk_div2 <= 1'b0;
		else if(cnt2<2) 
			clk_div2 <= 1'b1;
		else 
			clk_div2 <= 1'b0;
	end

	assign clk_div = clk_div1|clk_div2;


endmodule
